_BOXES = []
for _name, _rings in ZONES.items():
    for _ring in _rings:
        lats = [p[0] for p in _ring]
        lons = [p[1] for p in _ring]
        _BOXES.append((min(lats), max(lats), min(lons), max(lons), _ring))


def _in_ring(lat, lon, ring):
    inside = False
    j = len(ring) - 1
    for i in range(len(ring)):
        yi, xi = ring[i]
        yj, xj = ring[j]
        if (yi > lat) != (yj > lat):
            x = (xj - xi) * (lat - yi) / (yj - yi) + xi
            if lon < x:
                inside = not inside
        j = i
    return inside


def in_special_zone(lat, lon) -> bool:
    for la0, la1, lo0, lo1, ring in _BOXES:
        if la0 <= lat <= la1 and lo0 <= lon <= lo1 and _in_ring(lat, lon, ring):
            return True
    return False


def _hav(a, b):
    lat1, lon1 = map(math.radians, a)
    lat2, lon2 = map(math.radians, b)
    h = math.sin((lat2 - lat1) / 2) ** 2 + math.cos(lat1) * math.cos(lat2) * math.sin((lon2 - lon1) / 2) ** 2
    return 6371 * 2 * math.asin(math.sqrt(h))


def special_share(points) -> float:
    """Доля пути (0..1), проходящая по регионам с особым тарифом. points — [[lat, lon], ...]."""
    total = 0.0
    special = 0.0
    for i in range(len(points) - 1):
        a, b = points[i], points[i + 1]
        seg = _hav(a, b)
        if seg <= 0:
            continue
        total += seg
        if in_special_zone((a[0] + b[0]) / 2, (a[1] + b[1]) / 2):
            special += seg
    return special / total if total > 0 else 0.0


def straight_points(a, b, n=60):
    return [[a[0] + (b[0] - a[0]) * i / n, a[1] + (b[1] - a[1]) * i / n] for i in range(n + 1)]
